awk '
  /MARKER-start/ {
    print
    while ((getline line < "target/generated-sources/license/THIRD-PARTY.txt") > 0) {
      if (line != "") {
        sub(/^Lists/, "                        &", line)
        sub(/^     /, "                        <li>", line)
        print line "</li>"
      }
    }
    skip=1
    next
  }
  /MARKER-end/ { skip=0; print; next }
  !skip { print }
' src/main/resources/templates/about.html > /tmp/about.html.updated && mv /tmp/about.html.updated src/main/resources/templates/about.html && grep -n "spring-boot" src/main/resources/templates/about.html | head -20

